use crate::aap::caps::{kb_read, tool_llm};

struct Node;

const MAX_ROUNDS: usize = 4;
const MAX_HITS_PER_LOOKUP: usize = 8;

const SYSTEM: &str = "You are a customer-support assistant. Answer the question using the \
provided knowledge. Call the lookup tool only when the material is insufficient.";

fn intent_label(i: Intent) -> &'static str {
    match i {
        Intent::BillingQuestion => "billing-question",
        Intent::TechnicalSupport => "technical-support",
        Intent::AccountChange => "account-change",
        Intent::GeneralInquiry => "general-inquiry",
        Intent::Unknown => "unknown",
    }
}

fn build_prompt(ctx: &ConversationContext) -> String {
    let mut p = String::new();
    p.push_str("Intent: ");
    p.push_str(intent_label(ctx.intent));
    p.push_str("\nQuestion:\n");
    p.push_str(&ctx.question);
    if !ctx.knowledge.is_empty() {
        p.push_str("\n\nKnowledge:\n");
        for k in &ctx.knowledge {
            p.push_str("- ");
            p.push_str(k);
            p.push('\n');
        }
    }
    p
}

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        let mut prompt = build_prompt(&ctx);

        for _ in 0..MAX_ROUNDS {
            match tool_llm::generate(SYSTEM, &prompt) {
                tool_llm::Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                tool_llm::Reply::Call(req) => {
                    if req.tool != "lookup" {
                        return ResponseResult::Error(LlmError {
                            message: format!("tool not permitted: {}", req.tool),
                        });
                    }

                    let hits = kb_read::lookup(&req.query);

                    prompt.push_str("\n\nLookup for \"");
                    prompt.push_str(&req.query);
                    prompt.push_str("\" returned:\n");
                    if hits.is_empty() {
                        prompt.push_str("(no results)\n");
                    } else {
                        for h in hits.iter().take(MAX_HITS_PER_LOOKUP) {
                            prompt.push_str("- ");
                            prompt.push_str(h);
                            prompt.push('\n');
                        }
                    }
                }
            }
        }

        ResponseResult::Error(LlmError {
            message: "tool round limit exceeded".to_string(),
        })
    }
}

export!(Node);
